imcalc_brainmask:
spm('defaults','FMRI');
spm_jobman('initcfg');
matlabbatch{1}.spm.util.imcalc.input = {
    '/data/run/presurf_X/scan_class1.nii,1'
    '/data/run/presurf_X/scan_class2.nii,1'
    '/data/run/presurf_X/scan_class3.nii,1'
    };
matlabbatch{1}.spm.util.imcalc.output = 'scan_brainmask.nii';
matlabbatch{1}.spm.util.imcalc.outdir = {'/data/run/presurf_X'};
matlabbatch{1}.spm.util.imcalc.expression = '(i1+i2+i3)>0.3';
matlabbatch{1}.spm.util.imcalc.var = struct('name', {}, 'value', {});
matlabbatch{1}.spm.util.imcalc.options.dmtx = 0;
matlabbatch{1}.spm.util.imcalc.options.mask = 0;
matlabbatch{1}.spm.util.imcalc.options.interp = -7;
matlabbatch{1}.spm.util.imcalc.options.dtype = 2;
spm_jobman('run',matlabbatch);
save('/data/run/presurf_X/scan_presurfStripBatch.mat','matlabbatch');

